//! Tree-sitter language binding for GraphReact `.grx` markup.
//!
//! **M15 Phase 1B foundation.** Exposes a [`tree_sitter_language::LanguageFn`]
//! that any `tree-sitter::Parser` can attach to via `set_language`.
//! The actual parser tables come from [`src/parser.c`] (generated by
//! `tree-sitter generate` from [`grammar.js`]); the state-aware
//! scanner for `raw_body` is in [`src/scanner.c`].
//!
//! This crate is the canonical Rust binding to the grammar — both
//! [`graphreact-grx-parser`] (M15 Phase 1B incremental reparse) and
//! a future LSP server (M23) consume it through this API.
//!
//! # Re-generating the parser
//!
//! After editing [`grammar.js`], regenerate the parser tables:
//!
//! ```bash
//! cd tree-sitter-grx
//! tree-sitter generate
//! ```
//!
//! `build.rs` rebuilds the C objects on every change to `parser.c`,
//! `scanner.c`, or `grammar.js` (Cargo's `rerun-if-changed`).

#![allow(unsafe_code)]

use tree_sitter_language::LanguageFn;

extern "C" {
    fn tree_sitter_grx() -> *const ();
}

/// Tree-sitter language function for `.grx` markup. Attach via
/// `Parser::set_language(&LANGUAGE.into())`.
pub const LANGUAGE: LanguageFn = unsafe { LanguageFn::from_raw(tree_sitter_grx) };

/// Node type names exposed by the grammar. Useful for callers that
/// walk the syntax tree by name (the IR builder in
/// `graphreact-grx-parser` uses these).
pub mod kinds {
    pub const SOURCE_FILE: &str = "source_file";
    pub const COMMENT: &str = "comment";
    pub const IMPORT_DECL: &str = "import_decl";
    pub const GRAPH: &str = "graph";
    pub const GRAPH_NODE: &str = "graph_node";
    pub const GRAPH_NODE_OPEN: &str = "graph_node_open";
    pub const GRAPH_NODE_SELF_CLOSE: &str = "graph_node_self_close";
    pub const EDGE_DECL: &str = "edge_decl";
    pub const DEFINITION_BLOCK: &str = "definition_block";
    pub const RAW_BODY: &str = "raw_body";
    pub const ATTRIBUTE: &str = "attribute";
    pub const ATTR_NAME: &str = "attr_name";
    pub const STRING_LITERAL: &str = "string_literal";
    pub const EXPR_LITERAL: &str = "expr_literal";
    pub const TAG_NAME: &str = "tag_name";
    pub const IDENTIFIER: &str = "identifier";
    pub const ESCAPE_SEQUENCE: &str = "escape_sequence";
}
